using System;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The server's self test stops at "steam_appid.txt does not exist ... Please restart the server" when the file is
// missing (the game's own start batch file writes it). Write it before every start so the first start works too.
var root = (string)ThisService.RootDirectory;
var appIdFile = Path.Combine(root, "steam_appid.txt");
const string appId = "1326470";
if (!File.Exists(appIdFile) || File.ReadAllText(appIdFile).Trim() != appId)
{
    File.WriteAllText(appIdFile, appId);
    // Scripts run as the monitor; hand the file to the owner of the service folder.
    Globals.OperatingSystem.SetFileOwnerAutoDetect(appIdFile);
    ScriptConsole.WriteLine((object)"Wrote steam_appid.txt.");
}

//refAssemblies: System.Diagnostics.Process.dll, TCAdmin.Monitor.SDK.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine (Linux host) only: installs what the panel needs to run this Windows server - wine, winetricks, Xvfb and
// xdotool - with apt (Debian/Ubuntu) or dnf/yum (Red Hat), and the Windows runtimes listed in Verbs into the service's
// own Wine prefix. Idempotent: anything already present is skipped. Runs before the create/reinstall (host packages,
// so the panel's Wine check passes) and after it (prefix runtimes, once the service user and files exist).
if (!System.OperatingSystem.IsLinux()) return;

// Windows runtimes (winetricks verbs) the server needs inside the prefix. The server runs on Wine's built-in
// runtimes, so none are required today; add verbs here when a game update needs one.
var verbs = new string[] { };

var tools = new (string Command, string[] Apt, string[] Rpm)[]
{
    ("wine", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("wineserver", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("winetricks", new[] { "winetricks" }, new[] { "winetricks" }),
    ("cabextract", new[] { "cabextract" }, new[] { "cabextract" }),
    ("Xvfb", new[] { "xvfb" }, new[] { "xorg-x11-server-Xvfb", "xorg-x11-server-Xvfb.x86_64" }),
    ("xdotool", new[] { "xdotool" }, new[] { "xdotool" }),
};
var apt = Shell("command -v apt-get", out _);
var installer = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
var updated = false;
foreach (var tool in tools)
{
    if (Shell("command -v " + tool.Command, out _)) continue;
    var names = apt ? tool.Apt : tool.Rpm;
    ScriptConsole.WriteLine((object)(tool.Command + " is missing on this host; installing " + string.Join(" or ", names) + "."));
    var installed = names.Any(p => Shell(installer + p, out _));
    if (!installed && apt && !updated)
    {
        updated = Shell("DEBIAN_FRONTEND=noninteractive apt-get update", out _);
        installed = names.Any(p => Shell(installer + p, out _));
    }
    if (!installed || !Shell("command -v " + tool.Command, out _))
        throw new Exception(tool.Command + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
}
Shell("wine --version", out var wineVersion);
ScriptConsole.WriteLine((object)("Wine on this host: " + wineVersion.Trim()));

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
// Before the create/reinstall the service files and its run-as configuration do not exist yet.
string user = null;
if (File.Exists(Path.Combine(root, "SonsOfTheForestDS.exe")))
{
    try { user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName; }
    catch (FileNotFoundException) { }
}
if (string.IsNullOrEmpty(user) || !Shell("id -u '" + user + "'", out _))
{
    ScriptConsole.WriteLine((object)"The service is not created yet; the Wine prefix is prepared after the files are installed.");
    return;
}
var prefix = Path.Combine(root, ".wine");
// Every Wine call as the service user with the environment the panel starts the server with (root would leave
// root-owned files in the prefix).
var wineEnv = "runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root
              + "' WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' ";

// The first start creates the Wine prefix (about a minute), longer than the panel waits for the start that follows
// the create, so that start failed. Create the prefix here; the panel skips it when its marker file is present.
var marker = Path.Combine(prefix, ".tcadmin-initialized");
if (!File.Exists(marker))
{
    ScriptConsole.WriteLine((object)"Creating the Wine prefix (about a minute).");
    if (!Shell(wineEnv + "wineboot -u", out var bootOutput))
        throw new Exception("wineboot failed: " + string.Join("\n", bootOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"date -u +%Y-%m-%dT%H:%M:%SZ > '" + marker + "'\"", out _);
    ScriptConsole.WriteLine((object)"The Wine prefix is ready.");
}

if (verbs.Length == 0) return;
// winetricks records every verb it installed in the prefix.
var log = Path.Combine(prefix, "winetricks.log");
var done = File.Exists(log) ? File.ReadAllLines(log).Select(l => l.Trim()).ToHashSet() : new HashSet<string>();
var todo = verbs.Where(v => !done.Contains(v)).ToList();
if (todo.Count == 0)
{
    ScriptConsole.WriteLine((object)("Windows runtimes already installed: " + string.Join(", ", verbs) + "."));
    return;
}
ScriptConsole.WriteLine((object)("Installing " + string.Join(", ", todo) + " into the Wine prefix (a few minutes)."));
var command = wineEnv + "winetricks -q " + string.Join(" ", todo);
if (!Shell(command, out var output))
    throw new Exception("winetricks failed: " + string.Join("\n", output.Split('\n').TakeLast(15)));
Shell(wineEnv + "wineserver -w", out _);
ScriptConsole.WriteLine((object)"Windows runtimes installed.");

bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}
